#include "RefModel.h"
extern "C" void ref_model_eval(unsigned long long clk,unsigned long long reset,unsigned long long dat,unsigned long long addr,unsigned long long we,unsigned long long* ref_busy,unsigned long long* ref_SF_D,unsigned long long* ref_LCD_E,unsigned long long* ref_LCD_RS,unsigned long long* ref_LCD_RW){static VerilatedContext context;static RefModel model(&context);model.clk=clk;model.reset=reset;model.dat=dat;model.addr=addr;model.we=we;model.eval();*ref_busy=model.ref_busy;*ref_SF_D=model.ref_SF_D;*ref_LCD_E=model.ref_LCD_E;*ref_LCD_RS=model.ref_LCD_RS;*ref_LCD_RW=model.ref_LCD_RW;}
